mapper.insert:
		/*
             SQL ID : QstnVwitmDAO.qstnVwitmBulkRegist
             설  명 : 문항보기항목일괄등록
         */
         INSERT ALL

			INTO TB_LMS_QSTN_VWITM (
	         	  QSTN_VWITM_ID
				, QSTN_ID
				, QSTN_VWITM_GBNCD
				, QSTN_VWITM_CTS
				, CRANS_YN
				, QSTN_VWITM_SEQNO
				, RGTR_ID
				, REG_DTTM
	         ) VALUES (
	         	  #{item.qstnVwitmId}
				, #{item.qstnId}
				, #{item.qstnVwitmGbncd}
				, #{item.qstnVwitmCts}
				, #{item.cransYn}
				, #{item.qstnVwitmSeqno}
				, #{item.rgtrId}
				, FN_DTTM()
	         )

		SELECT * FROM DUAL

mapper.delete:
		/*
             SQL ID : QstnVwitmDAO.qstnVwitmDelete
             설  명 : 문항보기항목삭제
         */
         DELETE FROM TB_LMS_QSTN_VWITM
          WHERE QSTN_ID = #{qstnId}

mapper.insert:
/* SQL ID : QstnVwitmDAO.qstnVwitmCopy 설 명 : 문항보기항목가져오기 */ INSERT INTO TB_LMS_QSTN_VWITM ( QSTN_VWITM_ID , QSTN_ID , QSTN_VWITM_CTS , CRANS_YN , QSTN_VWITM_SEQNO , RGTR_ID , REG_DTTM ) SELECT FN_NEW_ID('QSVW') AS QSTN_VWITM_ID , A.* FROM (
SELECT #{item.qstnId} AS QSTN_ID , COALESCE(Q.QSTN_VWITM_CTS, B.VWITM_CTS) AS QSTN_VWITM_CTS , COALESCE(Q.CRANS_YN, B.CRANSYN) AS CRANS_YN , COALESCE(Q.QSTN_VWITM_SEQNO , B.VWITM_SEQNO) AS VWITM_SEQNO , #{item.rgtrId} AS RGTR_ID , FN_DTTM() AS REG_DTTM FROM DUAL LEFT JOIN TB_LMS_QSTN_VWITM Q ON Q.QSTN_ID = #{item.copyQstnId} LEFT JOIN TB_LMS_QBNK_QSTN_VWITM B ON B.QBNK_QSTN_ID = #{item.copyQstnId} WHERE (Q.QSTN_ID IS NOT NULL OR B.QBNK_QSTN_ID IS NOT NULL)
) A

mapper.update:
		/*
             SQL ID : QstnVwitmDAO.qstnVwitmBulkModify
             설  명 : 문항보기항목일괄수정
         */

         UPDATE TB_LMS_QSTN_VWITM SET
         	  MDFR_ID = #{item.mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, QSTN_VWITM_CTS = #{item.qstnVwitmCts}
         	, CRANS_YN = #{item.cransYn}
          WHERE QSTN_VWITM_ID = #{item.qstnVwitmId}
            AND QSTN_ID = #{item.qstnId}

mapper.delete:
/* SQL ID : QstnVwitmDAO.exrcsSddnQstnVwitmBulkDelete 설 명 : 연습돌발문항보기항목일괄삭제 */ DELETE FROM TB_LMS_QSTN_VWITM WHERE QSTN_ID IN ( SELECT QSTN_ID FROM TB_LMS_QSTN WHERE DELYN = 'N' AND (EXRCS_SDDN_QSTN_BSC_ID, QSTN_SEQNO) IN (
(#{item.exrcsSddnQstnBscId}, #{item.qstnSeqno})
)
)

mapper.select:
/* SQL ID : QstnVwitmDAO.profPreviewQstnVwitmList 설 명 : 교수미리보기문항보기항목목록조회 */ SELECT VWITM.QSTN_VWITM_ID , VWITM.QSTN_ID , VWITM.QSTN_VWITM_CTS , VWITM.CRANS_YN , EXAMPPR.LVL AS QSTN_VWITM_SEQNO FROM ( SELECT EXAMPPR.* , REGEXP_SUBSTR(EXAMPPR.QSTN_VWITM_DSPLY_SEQ, '[^@#]+', 1, LEVEL) AS VWITM_DSPLY_SEQNO , LEVEL AS LVL FROM (
SELECT #{item.qstnId} AS QSTN_ID , #{item.qstnSeqno} AS QSTN_DSPLY_SEQNO , #{item.searchValue} AS QSTN_VWITM_DSPLY_SEQ FROM DUAL
) EXAMPPR CONNECT BY LEVEL <= REGEXP_COUNT(EXAMPPR.QSTN_VWITM_DSPLY_SEQ, '@#') + 1 AND PRIOR EXAMPPR.QSTN_DSPLY_SEQNO = EXAMPPR.QSTN_DSPLY_SEQNO AND PRIOR DBMS_RANDOM.VALUE IS NOT NULL ) EXAMPPR JOIN TB_LMS_QSTN_VWITM VWITM ON EXAMPPR.QSTN_ID = VWITM.QSTN_ID AND EXAMPPR.VWITM_DSPLY_SEQNO = VWITM.QSTN_VWITM_SEQNO ORDER BY EXAMPPR.QSTN_DSPLY_SEQNO, EXAMPPR.LVL
